const Map<String, String> mahadashaPhalasTa = {
  'ರವಿ': 'சூரிய தசை அதிகாரம், தொழில் முன்னேற்றம் மற்றும் சுய-உணர்தல் ஆகியவற்றின் காலத்தைக் கொண்டுவருகிறது. அரசு அல்லது மேலதிகாரிகளிடமிருந்து சலுகைகளைப் பெறலாம்.',
  'ಚಂದ್ರ': 'சந்திர தசை என்பது உணர்ச்சி வளர்ச்சி, குடும்ப கவனம் மற்றும் சுற்றுச்சூழலில் மாற்றங்களுக்கான நேரம். மன அமைதி மற்றும் பொது தொடர்புகள் முன்னிலைப்படுத்தப்படுகின்றன.',
  'ಕುಜ': 'செவ்வாய் தசை அதிக ஆற்றல், தைரியம் மற்றும் செயல்பாட்டைக் கொண்டுவருகிறது. சொத்துக்களைப் பெறுவதற்கும், எதிரிகளை வெல்வதற்கும் இது ஒரு காலம்.',
  'ಬುಧ': 'புதன் தசை கற்றல், தகவல் தொடர்பு மற்றும் வணிக முயற்சிகளை வலியுறுத்துகிறது. அறிவுசார் நோக்கங்கள், எழுத்து மற்றும் பகுப்பாய்வு பணிகள் வெற்றியைக் கொண்டுவரும்.',
  'ಗುರು': 'குரு தசை பெரும்பாலும் வளர்ச்சி, ஞானம் மற்றும் ஒட்டுமொத்த செழிப்பின் காலமாகும். இது உயர்கல்வி, திருமணம் மற்றும் ஆன்மீக நடவடிக்கைகளுக்கு சாதகமானது.',
  'ಶುಕ್ರ': 'சுக்கிர தசை செல்வம், ஆடம்பரம், கலை ஈடுபாடுகள் மற்றும் காதல் உறவுகளின் காலமாகும். இது வாழ்க்கை வசதிகளையும் மகிழ்ச்சியையும் தருகிறது.',
  'ಶನಿ': 'சனி தசை ஒழுக்கம், கடின உழைப்பு மற்றும் சவால்களைத் தருகிறது. இது வாழ்க்கைப் பாடங்களைக் கற்பிக்கும் மற்றும் விடாமுயற்சியின் மூலம் நீண்டகால வெற்றியைத் தரும்.',
  'ರಾಹು': 'ராகு தசை லட்சியம், பொருள் ஆசைகள் மற்றும் திடீர் நிகழ்வுகளின் காலம். இது எதிர்பாராத வெற்றிகளைத் தரும், அதே சமயம் மனக்குழப்பங்களையும் உருவாக்கலாம்.',
  'ಕೇತು': 'கேது தசை ஆன்மீகத் தேடல், பற்றின்மை மற்றும் உள்ளுணர்வின் காலம். பொருள் வெற்றிகளை விட உள்நிலை வளர்ச்சிக்கு இது உகந்தது.',
};

